"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[28941],{88932(e,a,o){o.r(a),o.d(a,{assets:()=>t,contentTitle:()=>c,default:()=>u,frontMatter:()=>i,metadata:()=>n,toc:()=>d});const n=JSON.parse('{"id":"cursos/docker/modulos/introduccion-contenedores/cuestionario","title":"Cuestionario M01 \u2014 Introducci\xf3n a Contenedores","description":"Instrucci\xf3n: Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del","source":"@site/docs/cursos/docker/modulos/01-introduccion-contenedores/cuestionario.md","sourceDirName":"cursos/docker/modulos/01-introduccion-contenedores","slug":"/cursos/docker/modulos/introduccion-contenedores/cuestionario","permalink":"/sasf-temarios/cursos/docker/modulos/introduccion-contenedores/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/docker/modulos/introduccion-contenedores/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/docker/modulos/introduccion-contenedores/ejercicio"}}');var r=o(74848),s=o(28453);const i={sidebar_label:"Cuestionario"},c="Cuestionario M01 \u2014 Introducci\xf3n a Contenedores",t={},d=[{value:"1. [Investigar] \xbfQu\xe9 rol juega exactamente containerd en la arquitectura de Docker y c\xf3mo se diferencia de dockerd y runc? \xbfPor qu\xe9 containerd se convirti\xf3 en un proyecto graduado de la CNCF independiente de Docker?",id:"1-investigar-qu\xe9-rol-juega-exactamente-containerd-en-la-arquitectura-de-docker-y-c\xf3mo-se-diferencia-de-dockerd-y-runc-por-qu\xe9-containerd-se-convirti\xf3-en-un-proyecto-graduado-de-la-cncf-independiente-de-docker",level:3},{value:"2. [Investigar] \xbfQu\xe9 especifica exactamente la OCI Runtime Spec y por qu\xe9 runc es una implementaci\xf3n de referencia pero no la \xfanica? Mencion\xe1 al menos dos alternativas a runc y sus diferencias.",id:"2-investigar-qu\xe9-especifica-exactamente-la-oci-runtime-spec-y-por-qu\xe9-runc-es-una-implementaci\xf3n-de-referencia-pero-no-la-\xfanica-mencion\xe1-al-menos-dos-alternativas-a-runc-y-sus-diferencias",level:3},{value:"3. [Investigar] \xbfQu\xe9 es eBPF y c\xf3mo est\xe1 impactando el ecosistema de contenedores en \xe1reas como networking, seguridad y observabilidad? Mencion\xe1 proyectos concretos.",id:"3-investigar-qu\xe9-es-ebpf-y-c\xf3mo-est\xe1-impactando-el-ecosistema-de-contenedores-en-\xe1reas-como-networking-seguridad-y-observabilidad-mencion\xe1-proyectos-concretos",level:3},{value:"4. [Investigar] \xbfC\xf3mo funciona Podman en modo rootless y por qu\xe9 su arquitectura fork-exec se considera m\xe1s segura que el modelo cliente-servidor de Docker?",id:"4-investigar-c\xf3mo-funciona-podman-en-modo-rootless-y-por-qu\xe9-su-arquitectura-fork-exec-se-considera-m\xe1s-segura-que-el-modelo-cliente-servidor-de-docker",level:3},{value:"5. [Conectar] \xbfC\xf3mo se relacionan los Linux namespaces de la clase con el concepto de &quot;container breakout&quot;? \xbfQu\xe9 primitivas del kernel limitan realmente la capacidad de un proceso en un contenedor de escapar al host?",id:"5-conectar-c\xf3mo-se-relacionan-los-linux-namespaces-de-la-clase-con-el-concepto-de-container-breakout-qu\xe9-primitivas-del-kernel-limitan-realmente-la-capacidad-de-un-proceso-en-un-contenedor-de-escapar-al-host",level:3},{value:"6. [Conectar] La clase menciona OverlayFS como sistema de capas. \xbfC\xf3mo funciona exactamente a nivel de kernel el mecanismo copy-on-write y qu\xe9 diferencia hay entre overlay y overlay2?",id:"6-conectar-la-clase-menciona-overlayfs-como-sistema-de-capas-c\xf3mo-funciona-exactamente-a-nivel-de-kernel-el-mecanismo-copy-on-write-y-qu\xe9-diferencia-hay-entre-overlay-y-overlay2",level:3},{value:"7. [Conectar] \xbfC\xf3mo se relaciona el OCI Image Spec con el formato de imagen Docker tradicional y qu\xe9 cambios introdujo la spec v1.1 para soportar artefactos no-contenedor?",id:"7-conectar-c\xf3mo-se-relaciona-el-oci-image-spec-con-el-formato-de-imagen-docker-tradicional-y-qu\xe9-cambios-introdujo-la-spec-v11-para-soportar-artefactos-no-contenedor",level:3},{value:"8. [Cuestionar] &quot;Serverless va a matar a los contenedores&quot;. \xbfEs esto cierto o son tecnolog\xedas complementarias? Fundament\xe1 con casos reales.",id:"8-cuestionar-serverless-va-a-matar-a-los-contenedores-es-esto-cierto-o-son-tecnolog\xedas-complementarias-fundament\xe1-con-casos-reales",level:3},{value:"9. [Cuestionar] Docker Desktop cambi\xf3 su licencia en 2021 exigiendo pago a empresas grandes. \xbfFue una decisi\xf3n justa o un golpe a la comunidad? \xbfQu\xe9 alternativas open-source surgieron como respuesta?",id:"9-cuestionar-docker-desktop-cambi\xf3-su-licencia-en-2021-exigiendo-pago-a-empresas-grandes-fue-una-decisi\xf3n-justa-o-un-golpe-a-la-comunidad-qu\xe9-alternativas-open-source-surgieron-como-respuesta",level:3},{value:"10. [Cuestionar] \xbfSon los contenedores realmente &quot;m\xe1quinas virtuales ligeras&quot; o hay diferencias fundamentales que hacen esta analog\xeda peligrosa? \xbfEn qu\xe9 casos la analog\xeda VM-contenedor lleva a malas pr\xe1cticas?",id:"10-cuestionar-son-los-contenedores-realmente-m\xe1quinas-virtuales-ligeras-o-hay-diferencias-fundamentales-que-hacen-esta-analog\xeda-peligrosa-en-qu\xe9-casos-la-analog\xeda-vm-contenedor-lleva-a-malas-pr\xe1cticas",level:3}];function l(e){const a={code:"code",h1:"h1",h3:"h3",header:"header",hr:"hr",p:"p",strong:"strong",...(0,s.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(a.header,{children:(0,r.jsx)(a.h1,{id:"cuestionario-m01--introducci\xf3n-a-contenedores",children:"Cuestionario M01 \u2014 Introducci\xf3n a Contenedores"})}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Instrucci\xf3n"}),": Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del\r\ncontenido de la clase. No alcanza con lo visto en ",(0,r.jsx)(a.code,{children:"clase.md"}),".\r\nFundament\xe1 tus respuestas con fuentes, autores o ejemplos concretos."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"1-investigar-qu\xe9-rol-juega-exactamente-containerd-en-la-arquitectura-de-docker-y-c\xf3mo-se-diferencia-de-dockerd-y-runc-por-qu\xe9-containerd-se-convirti\xf3-en-un-proyecto-graduado-de-la-cncf-independiente-de-docker",children:"1. [Investigar] \xbfQu\xe9 rol juega exactamente containerd en la arquitectura de Docker y c\xf3mo se diferencia de dockerd y runc? \xbfPor qu\xe9 containerd se convirti\xf3 en un proyecto graduado de la CNCF independiente de Docker?"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": containerd es el runtime manager que gestiona el ciclo de vida completo del contenedor (pull de im\xe1genes, creaci\xf3n de snapshots, gesti\xf3n de storage, networking) y delega la ejecuci\xf3n de bajo nivel en runc. dockerd (daemon Docker) es la capa superior que expone la API REST, gestiona vol\xfamenes, redes, Swarm, y plugins. containerd se separ\xf3 de Docker en 2017 como donaci\xf3n a la CNCF, convirti\xe9ndose en proyecto graduado en 2019. Hoy containerd es usado por Kubernetes directamente (a trav\xe9s del CRI plugin) sin necesidad de dockerd."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": La arquitectura actual de Docker documentada en docker.com y el GitHub de containerd muestra que dockerd llama a containerd v\xeda gRPC, y containerd invoca runc usando la OCI runtime spec. containerd se dise\xf1\xf3 para ser un runtime manager independiente y portable, mientras dockerd agrega la experiencia de desarrollador (CLI, Compose, Swarm). La donaci\xf3n a CNCF fue estrat\xe9gica para permitir que Kubernetes y otros orquestadores usaran containerd como runtime sin dependencia de Docker, lo cual fue formalizado en K8s 1.20 con la deprecaci\xf3n de dockershim."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"2-investigar-qu\xe9-especifica-exactamente-la-oci-runtime-spec-y-por-qu\xe9-runc-es-una-implementaci\xf3n-de-referencia-pero-no-la-\xfanica-mencion\xe1-al-menos-dos-alternativas-a-runc-y-sus-diferencias",children:"2. [Investigar] \xbfQu\xe9 especifica exactamente la OCI Runtime Spec y por qu\xe9 runc es una implementaci\xf3n de referencia pero no la \xfanica? Mencion\xe1 al menos dos alternativas a runc y sus diferencias."}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": La OCI Runtime Spec (github.com/opencontainers/runtime-spec) define el formato ",(0,r.jsx)(a.code,{children:"config.json"})," y el ciclo de vida que un runtime debe implementar: create, start, state, kill, delete. Define el OCI bundle (config.json + root filesystem), hooks de prestart/poststart/poststop, Linux namespaces y capabilities, mounts, y seccomp. runc es la implementaci\xf3n de referencia (golang, ~100 MB), pero existen alternativas como crun (C, ~500 KB, ~4x m\xe1s r\xe1pido y con soporte cgroups v2 nativo y eBPF) y youki (Rust, enfocado en seguridad de memoria). Kubernetes soporta ambos a trav\xe9s del CRI."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": El OCI Runtime Spec (v1.1.0) define expl\xedcitamente que cualquier runtime que implemente estas operaciones es compatible. crun fue desarrollado por Red Hat (Giuseppe Scrivano) para ser m\xe1s r\xe1pido y ligero, y es el runtime por defecto en Podman y Fedora CoreOS. youki surgi\xf3 del inter\xe9s de la comunidad de Rust por tener un runtime memory-safe. La existencia de m\xfaltiples runtimes demuestra el \xe9xito del est\xe1ndar OCI: interoperabilidad real, no vendor lock-in."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"3-investigar-qu\xe9-es-ebpf-y-c\xf3mo-est\xe1-impactando-el-ecosistema-de-contenedores-en-\xe1reas-como-networking-seguridad-y-observabilidad-mencion\xe1-proyectos-concretos",children:"3. [Investigar] \xbfQu\xe9 es eBPF y c\xf3mo est\xe1 impactando el ecosistema de contenedores en \xe1reas como networking, seguridad y observabilidad? Mencion\xe1 proyectos concretos."}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": eBPF (extended Berkeley Packet Filter) permite ejecutar programas sandboxeados en el kernel Linux sin modificar el c\xf3digo fuente del kernel ni cargar m\xf3dulos. En contenedores, eBPF se usa para: 1) Networking \u2014 Cilium reemplaza kube-proxy con eBPF para load balancing O(1) en lugar de iptables O(n), 2) Seguridad \u2014 Falco usa eBPF para detectar llamadas al sistema an\xf3malas en tiempo real sin m\xf3dulo de kernel, 3) Observabilidad \u2014 Pixie (New Relic) usa eBPF para tracing autom\xe1tico sin instrumentaci\xf3n. Tambi\xe9n Tetragon (Isovalent/Cilium) implementa pol\xedticas de seguridad a nivel de kernel con eBPF."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": Brendan Gregg (Netflix, Intel) document\xf3 extensivamente c\xf3mo eBPF revoluciona la observabilidad (BPF Performance Tools, 2019). Thomas Graf (Cilium co-creator) demostr\xf3 que eBPF puede reemplazar iptables con mejor rendimiento y m\xe1s funcionalidad. La CNCF acept\xf3 Cilium como proyecto graduado en 2023, validando eBPF como tecnolog\xeda fundamental para cloud-native networking. eBPF permite inspeccionar paquetes, syscalls, y eventos del kernel con overhead m\xednimo (~1%), que es imposible con enfoques tradicionales de user-space."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"4-investigar-c\xf3mo-funciona-podman-en-modo-rootless-y-por-qu\xe9-su-arquitectura-fork-exec-se-considera-m\xe1s-segura-que-el-modelo-cliente-servidor-de-docker",children:"4. [Investigar] \xbfC\xf3mo funciona Podman en modo rootless y por qu\xe9 su arquitectura fork-exec se considera m\xe1s segura que el modelo cliente-servidor de Docker?"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": Podman (Red Hat) no tiene daemon central. Cada comando podman es un proceso independiente que usa fork-exec para crear contenedores directamente mediante runc/crun, sin un proceso persistente corriendo como root. En modo rootless, Podman usa user namespaces para mapear el UID 0 del contenedor a un UID no privilegiado del host, y slirp4netns/pasta para networking sin privilegios. Docker tambi\xe9n soporta rootless desde 2021, pero su arquitectura de daemon persiste como proceso de larga duraci\xf3n, lo que representa una superficie de ataque mayor."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": Daniel Walsh (Red Hat, creador de Podman) argument\xf3 en m\xfaltiples charlas (DevConf, Container Plumbing Days) que eliminar el daemon reduce la superficie de ataque: no hay un proceso root escuchando en un socket esperando comandos. El modelo fork-exec significa que si mat\xe1s el proceso podman, no hay nada corriendo. Podman rootless fue pionero: desde el kernel 4.18+ con user namespaces habilitados, cualquier usuario puede ejecutar contenedores sin privilegios ni membres\xeda al grupo docker. Docker implement\xf3 rootless posteriormente (Akihiro Suda, 2019-2021), pero requiere dockerd rootless corriendo como proceso del usuario, manteniendo la arquitectura cliente-servidor."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"5-conectar-c\xf3mo-se-relacionan-los-linux-namespaces-de-la-clase-con-el-concepto-de-container-breakout-qu\xe9-primitivas-del-kernel-limitan-realmente-la-capacidad-de-un-proceso-en-un-contenedor-de-escapar-al-host",children:'5. [Conectar] \xbfC\xf3mo se relacionan los Linux namespaces de la clase con el concepto de "container breakout"? \xbfQu\xe9 primitivas del kernel limitan realmente la capacidad de un proceso en un contenedor de escapar al host?'}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),': Los namespaces crean la ilusi\xf3n de aislamiento, pero no son una barrera de seguridad completa. Un "container breakout" explota que el kernel es compartido: si un proceso dentro del contenedor logra acceder a una syscall vulnerable o adquirir capabilities no restringidas, puede escapar de los namespaces. Las barreras reales son: user namespaces (mapeo de UIDs), seccomp (filtro de syscalls, ~44 bloqueadas por defecto por Docker), capabilities (Docker dropea CAP_SYS_ADMIN y otras peligrosas), y LSMs como AppArmor/SELinux. El caso m\xe1s famoso de breakout es CVE-2019-5736 (runc vulnerability) que permit\xeda sobrescribir el binario runc del host desde dentro del contenedor.']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),': Jessie Frazelle (ex-Docker, Microsoft) ha documentado extensivamente en su blog que "los contenedores no contienen" \u2014 los namespaces a\xedslan visibilidad, pero la seguridad real viene de capas adicionales. La OCI Runtime Spec define hooks y configuraciones de seguridad (seccomp, capabilities, LSMs) justamente porque los namespaces solos no bastan. El ataque CVE-2019-5736 explot\xf3 el hecho de que runc (el runtime que crea el contenedor) era accesible desde dentro del contenedor v\xeda /proc/self/exe \u2014 demostrando que sin seccomp y user namespaces restrictivos, el aislamiento de procesos es fr\xe1gil.']}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"6-conectar-la-clase-menciona-overlayfs-como-sistema-de-capas-c\xf3mo-funciona-exactamente-a-nivel-de-kernel-el-mecanismo-copy-on-write-y-qu\xe9-diferencia-hay-entre-overlay-y-overlay2",children:"6. [Conectar] La clase menciona OverlayFS como sistema de capas. \xbfC\xf3mo funciona exactamente a nivel de kernel el mecanismo copy-on-write y qu\xe9 diferencia hay entre overlay y overlay2?"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": OverlayFS (incluido en el kernel Linux desde 3.18) une m\xfaltiples directorios: lowerdir (capas de solo lectura, apiladas), upperdir (capa de escritura), y workdir (directorio de trabajo interno). Cuando un proceso modifica un archivo en lowerdir, OverlayFS copia el archivo completo a upperdir (copy-up) y la modificaci\xf3n se aplica ah\xed. El archivo original en lowerdir permanece intacto. overlay2 (kernel 4.0+) extiende el n\xfamero m\xe1ximo de lowerdir de 2 capas a 500 usando enlaces simb\xf3licos en un directorio de \xedndices, y soporta xattrs nativos y rename mejorado. Docker migr\xf3 de overlay a overlay2 como storage driver recomendado en 2017."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),': La documentaci\xf3n del kernel Linux (Documentation/filesystems/overlayfs.txt) y la presentaci\xf3n de Alexander Larsson (creador de OverlayFS) detallan el mecanismo de copy-up. overlay2 es m\xe1s eficiente porque reduce el consumo de inodos (usando enlaces en lugar de crear m\xfaltiples capas superpuestas) y soporta NFS como lowerdir. Miklos Szeredi (mantenedor de OverlayFS en el kernel) impuls\xf3 overlay2 para resolver el problema de "demasiadas capas" que las im\xe1genes Docker modernas requieren (una imagen t\xedpica tiene 10-20 capas). Docker usa overlay2 con la opci\xf3n ',(0,r.jsx)(a.code,{children:"index=off"})," para evitar operaciones de indexado innecesarias."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"7-conectar-c\xf3mo-se-relaciona-el-oci-image-spec-con-el-formato-de-imagen-docker-tradicional-y-qu\xe9-cambios-introdujo-la-spec-v11-para-soportar-artefactos-no-contenedor",children:"7. [Conectar] \xbfC\xf3mo se relaciona el OCI Image Spec con el formato de imagen Docker tradicional y qu\xe9 cambios introdujo la spec v1.1 para soportar artefactos no-contenedor?"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": El OCI Image Spec (github.com/opencontainers/image-spec) estandariz\xf3 el formato que Docker ya usaba: manifiestos, configs, y capas (blobs) identificados por digest SHA256. La imagen Docker y la imagen OCI son casi id\xe9nticas (misma estructura de archivos tar.gz para capas), con diferencias menores en el JSON de configuraci\xf3n y en el mediaType del manifiesto. La spec v1.1 (abril 2024) introdujo ",(0,r.jsx)(a.code,{children:"artifactType"})," en el manifiesto para diferenciar im\xe1genes de contenedor de otros artefactos (Helm charts, WASM modules, SBOMs) y formaliz\xf3 el campo ",(0,r.jsx)(a.code,{children:"subject"})," para referenciar artefactos relacionados (ej. una firma que apunta a su imagen), habilitando el ecosistema de supply chain security (Cosign, Notation)."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": La OCI Image Spec v1.0 (2017) consolid\xf3 el formato Docker v2.2 como est\xe1ndar abierto. La v1.1 fue impulsada por la necesidad de almacenar firmas y SBOMs en registries OCI sin depender de extensiones propietarias (como los ",(0,r.jsx)(a.code,{children:"cosign.sig"})," tags). Steve Lasker (Microsoft, chair OCI) lider\xf3 el esfuerzo para que OCI artifacts sean ciudadanos de primera clase. Esto permite que Harbor, ECR, ACR, y cualquier registry OCI-compliant almacene y sirva cualquier tipo de artefacto cloud-native, no solo im\xe1genes Docker."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"8-cuestionar-serverless-va-a-matar-a-los-contenedores-es-esto-cierto-o-son-tecnolog\xedas-complementarias-fundament\xe1-con-casos-reales",children:'8. [Cuestionar] "Serverless va a matar a los contenedores". \xbfEs esto cierto o son tecnolog\xedas complementarias? Fundament\xe1 con casos reales.'}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),': Son complementarias, no excluyentes. Los "serverless containers" (Cloud Run, AWS Fargate, ACI) unen ambos mundos: empaquet\xe1s tu app como contenedor (flexibilidad total de runtime y dependencias) pero la plataforma gestiona la infraestructura (escalado autom\xe1tico a cero, pago por uso). Kelsey Hightower (Google Cloud) populariz\xf3 la frase "Serverless is about the operational experience, not the technology". La tendencia no es "serverless mata contenedores" sino "todo se est\xe1 volviendo serverless en la experiencia operativa, con contenedores como formato de empaquetado".']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),': AWS Lambda ahora soporta im\xe1genes de contenedor (hasta 10 GB, 2021), Cloud Run siempre fue contenedores serverless, y Azure Container Apps es K8s serverless. El debate real no es contenedores vs serverless, sino cu\xe1ndo usar el modelo "pago por request" (Cloud Run/Lambda) vs "pago por recurso provisionado" (K8s/ECS). Para cargas con tr\xe1fico impredecible o que escalan a cero, serverless es m\xe1s econ\xf3mico. Para cargas estables 24/7, K8s puede ser m\xe1s barato. La industria converge: Kubernetes con KEDA escala a cero Pods, y serverless platforms adoptan OCI containers como formato universal.']}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"9-cuestionar-docker-desktop-cambi\xf3-su-licencia-en-2021-exigiendo-pago-a-empresas-grandes-fue-una-decisi\xf3n-justa-o-un-golpe-a-la-comunidad-qu\xe9-alternativas-open-source-surgieron-como-respuesta",children:"9. [Cuestionar] Docker Desktop cambi\xf3 su licencia en 2021 exigiendo pago a empresas grandes. \xbfFue una decisi\xf3n justa o un golpe a la comunidad? \xbfQu\xe9 alternativas open-source surgieron como respuesta?"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),': En agosto 2021, Docker Inc. anunci\xf3 que Docker Desktop requerir\xeda suscripci\xf3n paga (Pro, Team, Business) para empresas con m\xe1s de 250 empleados o $10M de ingresos. La comunidad reaccion\xf3 con indignaci\xf3n (muchos lo vieron como "bait and switch" despu\xe9s de a\xf1os de uso gratuito) pero tambi\xe9n con comprensi\xf3n (Docker Inc. necesitaba un modelo de negocio sostenible). Surgieron alternativas: Colima (Lima + containerd), Rancher Desktop (K8s + containerd/ dockerd), Podman Desktop, y Finch (AWS). Todas ofrecen funcionalidad similar sin costo ni restricciones de licencia.']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": Scott Johnston (CEO Docker Inc.) defendi\xf3 la decisi\xf3n en entrevistas como necesaria para la sostenibilidad financiera: Docker Desktop requer\xeda inversi\xf3n significativa en ingenier\xeda para soportar macOS y Windows con WSL 2/HyperKit. Por otro lado, empresas peque\xf1as, uso personal, educaci\xf3n, y open source siguen siendo gratuitos. El ecosistema open-source reaccion\xf3 creando alternativas maduras en meses: Colima de Abiosoft (l\xedder), Rancher Desktop de SUSE, y Podman Desktop de Red Hat. Para desarrollo local en equipos grandes, la decisi\xf3n forz\xf3 una evaluaci\xf3n: \xbfpagar $9-24/usuario/mes por Docker Desktop o migrar a alternativas gratuitas? Muchas startups migraron a Colima exitosamente."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"10-cuestionar-son-los-contenedores-realmente-m\xe1quinas-virtuales-ligeras-o-hay-diferencias-fundamentales-que-hacen-esta-analog\xeda-peligrosa-en-qu\xe9-casos-la-analog\xeda-vm-contenedor-lleva-a-malas-pr\xe1cticas",children:'10. [Cuestionar] \xbfSon los contenedores realmente "m\xe1quinas virtuales ligeras" o hay diferencias fundamentales que hacen esta analog\xeda peligrosa? \xbfEn qu\xe9 casos la analog\xeda VM-contenedor lleva a malas pr\xe1cticas?'}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),': Es una analog\xeda peligrosa porque oscurece diferencias fundamentales. Los contenedores no virtualizan hardware, comparten el kernel con el host, y no tienen su propio sistema operativo. La analog\xeda lleva a malas pr\xe1cticas como: 1) Tratar contenedores como "pets" (hacerles ',(0,r.jsx)(a.code,{children:"docker exec"}),' para debuggear, aplicar parches manualmente en lugar de reconstruir la imagen), 2) Ejecutar m\xfaltiples procesos en un contenedor "como una VM", 3) Usar ',(0,r.jsx)(a.code,{children:"docker commit"}),' para guardar estado en lugar de Dockerfiles, 4) No implementar graceful shutdown porque "las VMs tienen ACPI shutdown", 5) Instalar SSH dentro del contenedor "para administrarlo como un servidor".']}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),': Julia Evans (wizardzines.com) tiene una zine llamada "Containers aren\'t VMs" que explica esto visualmente. Kelsey Hightower dijo: "Stop treating containers like VMs. They\'re processes with isolation." La diferencia radica en que una VM es una abstracci\xf3n de hardware (hypervisor emula CPU, memoria, dispositivos) mientras un contenedor es una abstracci\xf3n de SO (kernel a\xedsla procesos con namespaces). Las buenas pr\xe1cticas de contenedores (un proceso, inmutabilidad, configuraci\xf3n externalizada) son antag\xf3nicas a las pr\xe1cticas de administraci\xf3n de VMs. Tratar contenedores como VMs es el error m\xe1s com\xfan en equipos que migran de infraestructura tradicional.']})]})}function u(e={}){const{wrapper:a}={...(0,s.R)(),...e.components};return a?(0,r.jsx)(a,{...e,children:(0,r.jsx)(l,{...e})}):l(e)}},28453(e,a,o){o.d(a,{R:()=>i,x:()=>c});var n=o(96540);const r={},s=n.createContext(r);function i(e){const a=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function c(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:i(e.components),n.createElement(s.Provider,{value:a},e.children)}}}]);